#include "this_access.hpp"
#include <cassert>
#include <cstdio>
static bool childAt(const ws::native::Result& r,int parent,int offset){for(auto a:r.accesses)if(a.base==ws::native::Origin::Child&&a.field==parent&&a.offset==offset)return true;return false;}
int main(){
 auto r=ws::native::analyze({0x48,0x89,0xcb,0x48,0x8b,0x83,0x88,0,0,0,0x0f,0x10,0x40,0x54,0xc3});assert(r.converged&&childAt(r,0x88,0x54));bool root=false;for(auto a:r.accesses)root|=a.base==ws::native::Origin::This&&a.offset==0x88&&a.pointerLoad&&a.width==8;assert(root);
 // A call clobbers RCX but preserves an already established RBX=this.
 auto call=ws::native::analyze({0x48,0x89,0xcb,0xe8,0,0,0,0,0x48,0x8b,0x81,0x80,0,0,0,0x48,0x8b,0x83,0x88,0,0,0,0x0f,0x10,0x40,0x54,0xc3});assert(childAt(call,0x88,0x54));for(auto a:call.accesses)assert(!(a.base==ws::native::Origin::This&&a.offset==0x80));
 auto killed=ws::native::analyze({0x48,0x8b,0x81,0x88,0,0,0,0x31,0xc0,0x0f,0x10,0x40,0x54,0xc3});assert(!childAt(killed,0x88,0x54));
 // Both paths meet at movups; one destroys RAX, so intersection must discard its provenance.
 auto join=ws::native::analyze({0x48,0x8b,0x81,0x88,0,0,0,0x85,0xd2,0x74,0x02,0x31,0xc0,0x0f,0x10,0x40,0x54,0xc3});assert(join.converged&&!childAt(join,0x88,0x54));
 auto indexed=ws::native::analyze({0x48,0x8b,0x04,0x91,0xc3});assert(indexed.accesses.empty());
 auto rip=ws::native::analyze({0x48,0x8b,0x05,0x88,0,0,0,0xc3});assert(rip.accesses.empty());
 auto truncated=ws::native::analyze({0x48,0x8b});assert(truncated.accesses.empty());
 // Do not treat BSWAP of a derived register as an SSE instruction preserving that pointer.
 auto swap=ws::native::analyze({0x48,0x8b,0x81,0x88,0,0,0,0x48,0x0f,0xc8,0x0f,0x10,0x40,0x54,0xc3});assert(!childAt(swap,0x88,0x54));
 auto depth=ws::native::analyze({0x48,0x8b,0x81,0x88,0,0,0,0x48,0x8b,0x50,0x10,0x0f,0x10,0x42,0x54,0xc3});assert(childAt(depth,0x88,0x10)&&!childAt(depth,0x88,0x54));
 auto highByte=ws::native::analyze({0x48,0x8b,0x81,0x88,0,0,0,0xb4,0,0x0f,0x10,0x40,0x54,0xc3});assert(!childAt(highByte,0x88,0x54));
 auto xchg=ws::native::analyze({0x48,0x8b,0x81,0x88,0,0,0,0x49,0x90,0x0f,0x10,0x40,0x54,0xc3});assert(!childAt(xchg,0x88,0x54));
 std::puts("PASS: native this-access provenance; RCX/RBX copies, one-level field dereference, call/write/CFG-merge invalidation, indexed/RIP/truncated/BSWAP rejection");
}
